const icon=name=>`<svg class="icon" viewBox="0 0 40 40" aria-hidden="true"><use href="/assets/tech/icons.svg#${name}"></use></svg>`;
function toast(text){let el=document.querySelector('.toast');if(!el){el=document.createElement('div');el.className='toast';el.role='status';document.body.append(el)}el.textContent=text;el.classList.add('show');clearTimeout(el.timer);el.timer=setTimeout(()=>el.classList.remove('show'),3500)}
const $=(s,r=document)=>r.querySelector(s),money=n=>Number(n||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='telomere-workspace-v1',initial={version:1,budget:0,plans:[],leashes:[],cysts:[],receipts:[],agents:[],records:[],preferences:{region:'Asia Pacific',currency:'USDC'}};
let state;try{state={...structuredClone(initial),...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch{state=structuredClone(initial)}
let tab='overview',search='',filter='all';
const tabs=[['overview','Overview'],['plans','Run plans'],['leashes','Leashes'],['cysts','Cyst policies'],['receipts','Receipts'],['selection','Selection'],['hosts','Hosts'],['settings','Settings']];
const appIcons={overview:'meter',plans:'cell',leashes:'leash',receipts:'receipt',cysts:'cyst',selection:'settlement',hosts:'host',settings:'compute'};
const main=$('#page-content');main.innerHTML=`<div class="console"><div class="console-mast"><div class="eyebrow">Telomere workspace / Base</div><div class="console-device mono">● &nbsp; DEVICE STORAGE <span class="muted"> / </span> 01</div></div><nav class="console-nav" aria-label="Workspace sections">${tabs.map(([id,n])=>`<button data-tab="${id}" class="${id==='overview'?'active':''}">${n}</button>`).join('')}</nav><section id="console-body"></section><nav class="workspace-appbar" aria-label="Quick workspace navigation">${['overview','plans','leashes','receipts'].map(id=>`<button data-tab="${id}" class="${id==='overview'?'active':''}">${icon(appIcons[id])}<span>${tabs.find(t=>t[0]===id)[1]}</span></button>`).join('')}<button id="workspace-more-button" aria-label="More workspace sections"><svg viewBox="0 0 40 40" aria-hidden="true"><circle cx="10" cy="20" r="2" fill="currentColor"/><circle cx="20" cy="20" r="2" fill="currentColor"/><circle cx="30" cy="20" r="2" fill="currentColor"/></svg><span>More</span></button></nav><dialog id="workspace-more"><div class="panel-head"><span class="mono">All workspace sections</span><button id="workspace-more-close" aria-label="Close workspace sections">×</button></div>${tabs.map(([id])=>`<button data-tab="${id}">${icon(appIcons[id])}<span>${tabs.find(t=>t[0]===id)[1]}</span><span>↗</span></button>`).join('')}<div class="more-site-links"><span class="mono muted">Explore Telomere</span>${[['Protocol','/protocol/'],['Compute','/compute/'],['For hosts','/hosts/'],['Field notes','/learn/'],['Interfaces','/developers/']].map(([n,h])=>`<a href="${h}">${n}<span>↗</span></a>`).join('')}</div></dialog><div class="console-foot mono"><span>OWNER CONTROL / EVERY RUN</span><span>USDC ON BASE <span class="orange">●</span></span></div></div><div class="drawer-scrim" hidden></div><aside class="console-drawer" role="dialog" aria-modal="true" aria-labelledby="drawer-title" hidden></aside><input type="file" accept="application/json,.json" id="receipt-file" hidden>`;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('Device storage is full. Export your workspace to keep a copy.')}}
function record(kind,label){state.records.unshift({id:crypto.randomUUID(),kind,label,date:new Date().toISOString()});state.records=state.records.slice(0,200)}
function nav(id){$('#workspace-more').close();$('#workspace-more-button').classList.toggle('active',!['overview','plans','leashes','receipts'].includes(id));tab=id;search='';filter='all';document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===id));render()}
$('.workspace-appbar').onclick=e=>{const b=e.target.closest('[data-tab]');if(b){nav(b.dataset.tab);window.scrollTo({top:0,behavior:'instant'})}};$('#workspace-more-button').onclick=()=>$('#workspace-more').showModal();$('#workspace-more-close').onclick=()=>$('#workspace-more').close();$('#workspace-more').onclick=e=>{const b=e.target.closest('[data-tab]');if(b){nav(b.dataset.tab);window.scrollTo({top:0,behavior:'instant'})}};
$('.console-nav').onclick=e=>{const b=e.target.closest('[data-tab]');if(b)nav(b.dataset.tab)};
const ceiling=()=>state.plans.filter(x=>x.status!=='Archived').reduce((n,p)=>n+ +p.ceiling,0);
const header=(k,h,p,action='')=>`<div class="console-heading"><div><span class="mono muted">${k}</span><h1>${h}</h1><p>${p}</p></div>${action}</div>`;
const btn=(text,action,primary=false)=>`<button class="pill${primary?' primary':''}" data-action="${action}">${text} <span>↗</span></button>`;
const empty=(i,h,p,action='')=>`<div class="console-empty">${icon(i)}<h3>${h}</h3><p>${p}</p>${action}</div>`;
function metric(n,label,detail){return `<div class="console-metric"><div class="mono muted">${label}</div><strong>${n}</strong><span>${detail}</span></div>`}
function chart(){const v=ceiling(),max=Math.max(v,state.budget,10),pts=[];for(let i=0;i<=24;i++){const y=205-(v/max)*150*i/24;pts.push(`${44+i*26.8},${y}`)}return `<div class="usage-chart"><div class="panel-head"><span>Planned spend</span><div class="mono muted">NEXT 24 HOURS</div></div><div class="chart-number">${money(v)} <span>USDC</span></div><svg viewBox="0 0 740 270" role="img" aria-label="Planned spend projection of ${money(v)} USDC"><g stroke="#d5d2cb" stroke-width="1">${[55,105,155,205].map(y=>`<path d="M44 ${y}H705"/>`).join('')}${[44,205,366,527,688].map(x=>`<path d="M${x} 35V205" stroke-dasharray="2 5"/>`).join('')}</g><polyline points="${pts.join(' ')}" fill="none" stroke="#fc5d24" stroke-width="2.5"/><circle cx="687" cy="${205-v/max*150}" r="5" fill="#fc5d24"/><g fill="#77766f" font-family="monospace" font-size="10"><text x="44" y="237">00:00</text><text x="205" y="237">06:00</text><text x="366" y="237">12:00</text><text x="527" y="237">18:00</text><text x="672" y="237">24:00</text><text x="7" y="58">${Math.ceil(max)}</text><text x="18" y="208">0</text></g></svg><div class="chart-caption"><span><i></i> Configured ceilings</span><span>Planning view / USDC</span></div></div>`}
function plansTable(limit=0){let list=state.plans.filter(p=>(!search||[p.name,p.hardware,p.id].join(' ').toLowerCase().includes(search.toLowerCase()))&&(filter==='all'||p.status===filter));if(limit)list=list.slice(0,limit);return list.length?`<div class="console-table-wrap"><table class="console-table"><thead><tr><th>WORKLOAD</th><th>HARDWARE</th><th>CEILING</th><th>STATUS</th><th></th></tr></thead><tbody>${list.map(p=>`<tr data-open="${p.id}" tabindex="0" role="button" aria-label="Open ${esc(p.name)}"><td><span class="table-workload">${icon('cell')}<span><strong>${esc(p.name)}</strong><small>${esc(p.id.slice(0,12))}</small></span></span></td><td>${esc(p.hardware)}<small>${esc(p.lane)}</small></td><td>${money(p.ceiling)} <small>USDC</small></td><td><span class="status ${p.status==='Blocked'?'blocked':''}"><i></i>${esc(p.status)}</span></td><td class="row-arrow">↗</td></tr>`).join('')}</tbody></table></div>`:empty('cell',search?'No matching run plans.':'Your next run starts here.','Choose hardware, define an image, and set a spending ceiling.',btn('Configure a cell','new-plan',true))}
function overview(){return header('CONTROL PLANE / 01','Your compute.<br><span class="orange">Under control.</span>','Prepare work. Set boundaries. Keep a precise record.',btn('Configure a cell','new-plan',true))+`<div class="console-metrics">${metric(String(state.plans.filter(p=>p.status==='Prepared').length).padStart(2,'0'),'Run plans','Prepared configurations')}${metric(String(state.leashes.filter(l=>!l.killed).length).padStart(2,'0'),'Active Leashes','Owner-defined policies')}${metric(String(state.cysts.length).padStart(2,'0'),'Cyst policies','Portable state settings')}${metric(money(ceiling()),'Planned ceilings','USDC across run plans')}</div><div class="console-main-grid">${chart()}<div class="budget-panel"><div class="panel-head"><span>Budget policy</span>${icon('leash')}</div><div class="mono muted">WORKSPACE LIMIT</div><div class="budget-number">${money(state.budget)}<span>USDC</span></div><div class="budget-track"><i style="width:${state.budget?Math.min(100,ceiling()/state.budget*100):0}%"></i></div><div class="budget-numbers"><span>Allocated ${money(ceiling())}</span><span>${state.budget?Math.max(0,100-ceiling()/state.budget*100).toFixed(0):100}% free</span></div><p>Define a planning budget before configuring your workload.</p><button class="text-link" data-action="budget">${state.budget?'Edit budget policy':'Set a budget'} <span>↗</span></button></div></div><section class="console-section"><div class="panel-head"><h2>Run plans <span class="count">${state.plans.length}</span></h2><button class="quiet-button" data-action="all-plans">View all ↗</button></div>${plansTable(4)}</section><div class="console-lower"><section class="primitive-panel"><span class="mono muted">THE RUN STANDARD</span><h3>One ceiling.<br>Every second accounted for.</h3><div class="seconds-strip"><i></i>${Array.from({length:15},(_,i)=>`<b class="${i>10?'unused':''}"></b>`).join('')}<i></i></div><div class="mono strip-labels"><span>RAN / SETTLED</span><span>UNUSED / REFUNDED</span></div><a class="text-link" href="/learn/receipts/">Understand Run Receipts <span>↗</span></a></section><section class="activity-panel"><div class="panel-head"><h2>Workspace record</h2><button class="quiet-button" data-action="export-workspace">Export ↗</button></div>${state.records.length?state.records.slice(0,4).map(r=>`<div class="activity-row"><span class="activity-dot"></span><div><strong>${esc(r.label)}</strong><small>${esc(r.kind)} / ${new Date(r.date).toLocaleDateString('en-US',{timeZone:'America/New_York',day:'2-digit',month:'short'})}</small></div><span>↗</span></div>`).join(''):`<p class="activity-empty">Your configuration activity will appear here.<br>Every change stays in your workspace record.</p>`}</section></div>`}
function planPage(){return header('COMPUTE / 02','Run plans.','Define hardware, duration, an image, and a bounded spend.',btn('Configure a cell','new-plan',true))+`<div class="table-toolbar"><input id="plan-search" type="search" placeholder="Search workloads or hardware" aria-label="Search run plans" value="${esc(search)}"><select id="plan-filter" aria-label="Filter run plans"><option value="all">All statuses</option><option>Prepared</option><option>Blocked</option><option>Archived</option></select><button class="quiet-button" data-action="export-plans">Export JSON ↓</button></div><div class="console-section" id="plans-table">${plansTable()}</div>`}
function leashPage(){return header('OWNER CONTROL / 03','The Leash.','A policy for spending authority, workload boundaries, and an instant stop.',btn('Create a Leash','new-leash',true))+`<div class="console-object-grid">${state.leashes.map(l=>`<article class="console-object"><div class="panel-head">${icon('leash')}<span class="status ${l.killed?'blocked':''}"><i></i>${l.killed?'Revoked':'Active'}</span></div><h2>${esc(l.name)}</h2><div class="object-pair"><span>Hourly maximum</span><strong>${money(l.hourly)} USDC</strong></div><div class="object-pair"><span>Daily maximum</span><strong>${money(l.daily)} USDC</strong></div><div class="object-pair"><span>Hardware</span><strong>${esc(l.hardware)}</strong></div><div class="object-pair"><span>Host rule</span><strong>${l.sealed?'Sealed only':'All eligible hosts'}</strong></div><div class="object-pair"><span>Expiry</span><strong>${esc(l.expiry||'Not set')}</strong></div><div class="object-actions"><button data-leash-edit="${l.id}">Edit policy ↗</button><button data-leash-kill="${l.id}" ${l.killed?'disabled':''}>${l.killed?'Revoked':'Revoke authority'}</button></div></article>`).join('')}</div>${!state.leashes.length?empty('leash','Authority starts with a boundary.','Set hourly and daily caps, an allowed class, and an expiry.',btn('Create a Leash','new-leash',true)):''}`}
function cystPage(){return header('CONTINUITY / 04','State that stays.','Prepare snapshot and resume policies for workload continuity.',btn('Create Cyst policy','new-cyst',true))+`${!state.cysts.length?empty('cyst','Keep a path back.','Define a checkpoint interval, state directory, and resume policy.',btn('Create Cyst policy','new-cyst',true)):`<div class="console-object-grid">${state.cysts.map(c=>`<article class="console-object"><div class="panel-head">${icon('cyst')}<span class="mono muted">POLICY</span></div><h2>${esc(c.name)}</h2><div class="object-pair"><span>Checkpoint interval</span><strong>${esc(c.interval)} minutes</strong></div><div class="object-pair"><span>State path</span><code>${esc(c.directory)}</code></div><div class="object-pair"><span>Encryption</span><strong>XChaCha20-Poly1305</strong></div><div class="object-pair"><span>Sealed key release</span><strong>${c.sealed?'Required':'Optional'}</strong></div><div class="object-actions"><button data-export-cyst="${c.id}">Export policy ↓</button><button data-remove-cyst="${c.id}">Remove</button></div></article>`).join('')}</div>`}<div class="console-note">${icon('cyst')}<p>Cyst policies describe how a workload should checkpoint. The encrypted snapshot is produced by its connected runtime.</p><a href="/learn/cysts/">Read the Cyst standard ↗</a></div>`}
function receiptPage(){return header('VERIFIABLE RECORDS / 05','Every second,<br>recorded.','Import host-signed Run Receipt files and keep the record of settled work.',btn('Import receipt','import-receipt',true))+`<div class="console-metrics">${metric(String(state.receipts.length).padStart(2,'0'),'Imported receipts','Run records on this device')}${metric(state.receipts.reduce((n,r)=>n+ +r.billable_seconds,0).toLocaleString(),'Billable seconds','From imported records')}${metric(money(state.receipts.reduce((n,r)=>n+ +r.amount_usdc,0)),'Settled amount','USDC in imported records')}${metric('Base','Settlement chain','Hourly receipt roots')}</div><div class="console-section"><div class="panel-head"><h2>Receipt archive</h2><button class="quiet-button" data-action="export-receipts">Export CSV ↓</button></div>${state.receipts.length?`<div class="console-table-wrap"><table class="console-table"><thead><tr><th>RUN ID</th><th>CLASS</th><th>SECONDS</th><th>AMOUNT</th><th>RECORD</th></tr></thead><tbody>${state.receipts.map(r=>`<tr><td>${esc(r.run_id)}</td><td>${esc(r.hw_class)}</td><td>${Number(r.billable_seconds).toLocaleString()}</td><td>${money(r.amount_usdc)} USDC</td><td><span class="status neutral">Imported</span></td></tr>`).join('')}</tbody></table></div>`:empty('receipt','The record follows the run.','Import a receipt JSON file to inspect its recorded seconds and settlement amount.',btn('Import receipt','import-receipt'))}</div><div class="console-note">${icon('receipt')}<p>A receipt connects meter ticks, an hourly root, and escrow settlement events. An imported record requires independent signature and root verification.</p><a href="/learn/receipts/">Receipt verification ↗</a></div>`}
function selectionPage(){return header('PUBLIC AGENT LIFE / 06','Selection.','Prepare agent profiles with a budget policy and declared income endpoints.',btn('Prepare an agent','new-agent',true))+`${!state.agents.length?empty('settlement','An agent with a path to survive.','Define a profile, attach a Leash, and declare its service endpoint.',btn('Prepare an agent','new-agent',true)):`<div class="console-object-grid">${state.agents.map(a=>`<article class="console-object"><div class="panel-head">${icon('settlement')}<span class="status neutral">Prepared</span></div><h2>${esc(a.name)}</h2><div class="object-pair"><span>Initial ceiling</span><strong>${money(a.budget)} USDC</strong></div><div class="object-pair"><span>Service endpoint</span><strong>${esc(a.endpoint||'Not set')}</strong></div><div class="object-pair"><span>Maximum living offspring</span><strong>3</strong></div><div class="object-actions"><button data-export-agent="${a.id}">Export profile ↓</button></div></article>`).join('')}</div>`}<section class="primitive-panel" style="margin-top:30px"><span class="mono muted">THE FOSSIL RECORD</span><h3>Birth. Income. Burn.<br>Dormancy. Death.</h3><p>Selection records are derived from on-chain events and receipts. Owner top-ups are tracked separately from self-funded income.</p><a class="text-link" href="/learn/selection/">Understand Selection <span>↗</span></a></section>`}
function hostsPage(){const hosts=JSON.parse(localStorage.getItem('telomere-hosts')||'[]');return header('SUPPLY / 07','Host profiles.','Capacity configurations saved from the Host Kit page.',`<a class="pill primary" href="/hosts/#host-profile">Prepare a host ↗</a>`)+`${hosts.length?`<div class="console-object-grid">${hosts.map(h=>`<article class="console-object"><div class="panel-head">${icon('host')}<span class="status neutral">Prepared</span></div><h2>${esc(h.label)}</h2><div class="object-pair"><span>Hardware</span><strong>${esc(h.hardware)}</strong></div><div class="object-pair"><span>Region</span><strong>${esc(h.region)}</strong></div><div class="object-pair"><span>Posted rate</span><strong>${money(h.rate)} USDC / h</strong></div><div class="object-actions"><button data-host-export="${h.id}">Export profile ↓</button></div></article>`).join('')}</div>`:empty('host','Capacity begins with a profile.','Prepare hardware, region, and pricing information for an independent host.','<a class="pill" href="/hosts/#host-profile">Prepare a host ↗</a>')}`}
function settingsPage(){return header('WORKSPACE / 08','Your preferences.','Manage this device’s workspace, export records, and set default planning values.')+`<div class="settings-grid"><form id="settings-form" class="console-object"><h2>Planning defaults</h2><label class="field"><span>Default region</span><select name="region">${['Asia Pacific','Europe','North America'].map(r=>`<option ${r===state.preferences.region?'selected':''}>${r}</option>`).join('')}</select></label><label class="field"><span>Settlement asset</span><input value="USDC / Base" readonly></label><button class="pill primary" style="margin-top:25px">Save preferences ↗</button></form><div class="console-object"><h2>Workspace data</h2><p>Configurations and imported records are saved on this device. Export a copy before clearing browser storage.</p><div class="object-pair"><span>Run configurations</span><strong>${state.plans.length}</strong></div><div class="object-pair"><span>Saved policies</span><strong>${state.leashes.length+state.cysts.length}</strong></div><div class="object-pair"><span>Imported receipts</span><strong>${state.receipts.length}</strong></div><button class="text-link" data-action="export-workspace">Export complete workspace <span>↓</span></button><button class="text-link muted" data-action="reset">Clear workspace data <span>↗</span></button></div></div>`}
function render(){const body=$('#console-body');body.innerHTML=({overview,plans:planPage,leashes:leashPage,cysts:cystPage,receipts:receiptPage,selection:selectionPage,hosts:hostsPage,settings:settingsPage})[tab]();if($('#plan-filter'))$('#plan-filter').value=filter;bind()}
function download(name,data,type='application/json'){const blob=new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),500)}
function requestFor(p){return{method:'POST',path:'/v1/cells',body:{class:p.hardware,lane:p.lane.toLowerCase(),image:p.image,max_usd:+p.ceiling,max_seconds:+p.minutes*60,leash_id:p.leash||null,sealed_only:p.lane==='Sealed',region:p.region}}}
let previousFocus;
function drawer(title,content,onSubmit){previousFocus=document.activeElement;const d=$('.console-drawer'),scrim=$('.drawer-scrim');d.innerHTML=`<div class="drawer-head"><div><span class="mono muted">TELOMERE / CONFIGURATION</span><h2 id="drawer-title">${title}</h2></div><button aria-label="Close panel" class="drawer-close">×</button></div>${content}`;d.hidden=false;scrim.hidden=false;document.body.style.overflow='hidden';requestAnimationFrame(()=>d.classList.add('open'));$('.drawer-close').onclick=closeDrawer;scrim.onclick=closeDrawer;if(onSubmit)d.querySelector('form').onsubmit=e=>{e.preventDefault();onSubmit(Object.fromEntries(new FormData(e.currentTarget)),e.currentTarget)};d.querySelector('input,select,button')?.focus()}
function closeDrawer(){const d=$('.console-drawer');d.classList.remove('open');d.hidden=true;$('.drawer-scrim').hidden=true;document.body.style.overflow='';previousFocus?.focus()}
document.addEventListener('keydown',e=>{if(!document.body.classList.contains('dashboard-page')||$('.console-drawer').hidden)return;if(e.key==='Escape')closeDrawer();if(e.key==='Tab'){const nodes=[...$('.console-drawer').querySelectorAll('a,button,input,select,textarea')].filter(n=>!n.disabled),first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault()}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault()}}});
const field=(label,name,type='text',value='',extra='')=>`<label class="field"><span>${label}</span><input type="${type}" name="${name}" value="${esc(value)}" ${extra}></label>`;
const select=(label,name,options,current='')=>`<label class="field"><span>${label}</span><select name="${name}">${options.map(x=>{const [val,label]=Array.isArray(x)?x:[x,x];return `<option value="${esc(val)}" ${val===current?'selected':''}>${esc(label)}</option>`}).join('')}</select></label>`;
function newPlan(pending={}){
 const p={name:'',hardware:'CPU',lane:'Standard',minutes:60,rate:1,image:'ubuntu:24.04',ceiling:5,region:state.preferences.region,...pending};
 drawer('Configure a cell',`<form class="drawer-form">${field('Workload label','name','text',p.name,'required maxlength="48" placeholder="inference-worker-01"')}<div class="form-row">${select('Hardware class','hardware',['CPU','RTX','A100','H100','H200','B200'],p.hardware)}${select('Lane','lane',['Standard','Interruptible','Sealed'],p.lane)}</div>${field('Workload image','image','text',p.image,'required maxlength="180"')}<div class="form-row">${field('Maximum minutes','minutes','number',p.minutes,'required min="1" max="1440"')}${field('Planning rate / USDC per hour','rate','number',p.rate,'required min="0" step="0.01"')}</div><div class="form-row">${field('Spending ceiling / USDC','ceiling','number',p.ceiling,'required min="0.01" max="250" step="0.01"')}${select('Region','region',['Asia Pacific','Europe','North America'],p.region)}</div>${select('Leash policy','leash',[['','No policy attached'],...state.leashes.filter(l=>!l.killed).map(l=>[l.id,l.name])],p.leash)}<div class="form-summary"><span class="mono">Estimated plan cost</span><strong id="drawer-cost">0.00</strong></div><p class="form-help">The planning rate is your input. A supplier quote sets the final per-second rate before execution.</p><div class="form-error" role="alert"></div><button class="pill primary" type="submit">Save run plan <span>↗</span></button></form>`,v=>{
  const estimated=+v.rate*(+v.minutes/60)*(v.lane==='Sealed'?1.12:1.09),leash=state.leashes.find(l=>l.id===v.leash);
  let err='';if(estimated>+v.ceiling+.0001)err='The estimated cost exceeds the ceiling. Adjust the duration, rate, or ceiling.';
  if(state.budget&&ceiling()+ +v.ceiling>state.budget+.0001)err='This ceiling would exceed the workspace planning budget.';
  if(leash&&(+v.ceiling>+leash.daily||+v.rate*(v.lane==='Sealed'?1.12:1.09)>+leash.hourly))err='This plan exceeds its Leash spending limits.';
  if(leash?.hardware!=='Any'&&leash&&leash.hardware!==v.hardware)err='Choose hardware allowed by the selected Leash.';
  if(leash?.sealed&&v.lane!=='Sealed')err='This Leash requires sealed hosts.';
  if(leash?.expiry&&new Date(leash.expiry+'T23:59:59')<new Date())err='This Leash has expired. Attach an active policy.';
  if(err){$('.form-error').textContent=err;return}
  state.plans.unshift({...v,id:'run_'+crypto.randomUUID().slice(0,12),status:'Prepared',created:new Date().toISOString()});record('Run plan',v.name+' prepared');save();closeDrawer();nav('plans');toast('Run plan saved. Export the request when ready.');
 });
 const form=$('.drawer-form');const cost=()=>{const v=Object.fromEntries(new FormData(form));$('#drawer-cost').textContent=money(+v.rate*(+v.minutes/60)*(v.lane==='Sealed'?1.12:1.09))+' USDC'};form.addEventListener('input',cost);cost();
}
function planDetails(id){const p=state.plans.find(p=>p.id===id);if(!p)return;drawer(esc(p.name),`<div class="drawer-form"><span class="status"><i></i>${p.status}</span><div class="object-pair"><span>Run identifier</span><code>${esc(p.id)}</code></div><div class="object-pair"><span>Hardware / lane</span><strong>${esc(p.hardware)} / ${esc(p.lane)}</strong></div><div class="object-pair"><span>Maximum duration</span><strong>${p.minutes} minutes</strong></div><div class="object-pair"><span>Spending ceiling</span><strong>${money(p.ceiling)} USDC</strong></div><div class="object-pair"><span>Region</span><strong>${esc(p.region)}</strong></div><div class="object-pair"><span>Leash</span><strong>${esc(state.leashes.find(l=>l.id===p.leash)?.name||'Not attached')}</strong></div><h3>Run request</h3><pre class="code-block">${esc(JSON.stringify(requestFor(p),null,2))}</pre><button class="pill primary" id="export-request">Export request ↓</button><button class="pill" id="duplicate-plan">Duplicate plan ↗</button><button class="text-link muted" id="archive-plan">${p.status==='Archived'?'Restore plan':'Archive plan'} ↗</button></div>`);$('#export-request').onclick=()=>download(p.name+'-request.json',requestFor(p));$('#duplicate-plan').onclick=()=>{closeDrawer();newPlan({...p,name:p.name+'-copy'})};$('#archive-plan').onclick=()=>{p.status=p.status==='Archived'?'Prepared':'Archived';record('Run plan',p.name+' '+p.status.toLowerCase());save();closeDrawer();render();toast('Run plan updated.')};}
function budget(){drawer('Set your boundary.',`<form class="drawer-form"><p class="drawer-intro">Set the total ceiling for the run plans in this workspace.</p>${field('Workspace budget / USDC','budget','number',state.budget||100,'required min="0" max="1000000" step="0.01"')}<p class="form-help">A planning budget defines a boundary for configurations saved on this device. It does not move funds.</p><div class="form-error" role="alert"></div><button class="pill primary">Save budget policy ↗</button></form>`,v=>{if(+v.budget&&+v.budget<ceiling()){$('.form-error').textContent='The budget must cover the existing planned ceilings.';return}state.budget=+v.budget;record('Budget policy','Workspace boundary updated');save();closeDrawer();render();toast('Budget policy saved.')})}
function newLeash(existing){const l=existing||{name:'',hourly:20,daily:200,hardware:'Any',expiry:'',sealed:false};drawer(existing?'Edit Leash':'Create a Leash',`<form class="drawer-form">${field('Policy label','name','text',l.name,'required maxlength="48" placeholder="gpu-workloads"')}<div class="form-row">${field('Maximum per hour / USDC','hourly','number',l.hourly,'required min="0.01" max="1000" step="0.01"')}${field('Maximum per day / USDC','daily','number',l.daily,'required min="0.01" max="1000" step="0.01"')}</div>${select('Allowed hardware','hardware',['Any','CPU','RTX','A100','H100','H200','B200'],l.hardware)}${field('Expiry','expiry','date',l.expiry)}<label class="check-field"><input type="checkbox" name="sealed" ${l.sealed?'checked':''}> Require sealed hosts only</label><p class="form-help">A saved policy can be attached to run configurations. Export it for contract integration.</p><div class="form-error" role="alert"></div><button class="pill primary">Save Leash policy ↗</button></form>`,v=>{if(+v.hourly>+v.daily){$('.form-error').textContent='The daily limit must be at least the hourly limit.';return}const updated={...v,sealed:!!v.sealed,id:existing?.id||'leash_'+crypto.randomUUID().slice(0,10),killed:existing?.killed||false};if(existing)Object.assign(existing,updated);else state.leashes.unshift(updated);record('Leash',v.name+' saved');save();closeDrawer();render();toast('Leash policy saved.')})}
function newCyst(){drawer('Create Cyst policy',`<form class="drawer-form">${field('Policy label','name','text','','required maxlength="48" placeholder="persistent-worker"')}${field('State directory','directory','text','/workspace/state','required')}${field('Checkpoint interval / minutes','interval','number',15,'required min="1" max="1440"')}<label class="check-field"><input type="checkbox" name="sealed"> Require attestation-gated key release</label><button class="pill primary">Save Cyst policy ↗</button></form>`,v=>{state.cysts.unshift({...v,id:'cyst_'+crypto.randomUUID().slice(0,10),sealed:!!v.sealed});record('Cyst policy',v.name+' saved');save();closeDrawer();render();toast('Cyst policy saved.')})}
function newAgent(){drawer('Prepare an agent',`<form class="drawer-form">${field('Agent identifier','name','text','','required maxlength="48" placeholder="compute-agent-01"')}${field('Initial ceiling / USDC','budget','number',0,'required min="0" max="2500" step="0.01"')}${field('Declared service endpoint','endpoint','url','','placeholder="https://"')}${select('Leash policy','leash',[['','Choose a policy'],...state.leashes.filter(l=>!l.killed).map(l=>[l.id,l.name])])}<p class="form-help">Prepare the profile before registration with SelectionRegistry.</p><button class="pill primary">Save agent profile ↗</button></form>`,v=>{state.agents.unshift({...v,id:'agent_'+crypto.randomUUID().slice(0,10)});record('Agent profile',v.name+' prepared');save();closeDrawer();render();toast('Agent profile saved.')})}
function bind(){
 document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));
 document.querySelectorAll('[data-open]').forEach(r=>{r.onclick=()=>planDetails(r.dataset.open);r.onkeydown=e=>{if(e.key==='Enter')planDetails(r.dataset.open)}});
 $('#plan-search')?.addEventListener('input',e=>{search=e.target.value;$('#plans-table').innerHTML=plansTable();bindRows()});$('#plan-filter')?.addEventListener('change',e=>{filter=e.target.value;$('#plans-table').innerHTML=plansTable();bindRows()});
 document.querySelectorAll('[data-leash-edit]').forEach(b=>b.onclick=()=>newLeash(state.leashes.find(l=>l.id===b.dataset.leashEdit)));
 document.querySelectorAll('[data-leash-kill]').forEach(b=>b.onclick=()=>{const l=state.leashes.find(l=>l.id===b.dataset.leashKill);l.killed=true;state.plans.filter(p=>p.leash===l.id&&p.status==='Prepared').forEach(p=>p.status='Blocked');record('Leash',l.name+' revoked');save();render();toast('Authority revoked. Linked run plans are blocked.')});
 document.querySelectorAll('[data-export-cyst]').forEach(b=>b.onclick=()=>download('telomere-cyst-policy.json',state.cysts.find(c=>c.id===b.dataset.exportCyst)));
 document.querySelectorAll('[data-remove-cyst]').forEach(b=>b.onclick=()=>{state.cysts=state.cysts.filter(c=>c.id!==b.dataset.removeCyst);save();render();toast('Cyst policy removed.')});
 document.querySelectorAll('[data-export-agent]').forEach(b=>b.onclick=()=>download('telomere-agent-profile.json',state.agents.find(a=>a.id===b.dataset.exportAgent)));
 document.querySelectorAll('[data-host-export]').forEach(b=>b.onclick=()=>download('telomere-host-profile.json',JSON.parse(localStorage.getItem('telomere-hosts')||'[]').find(h=>h.id===b.dataset.hostExport)));
 $('#settings-form')?.addEventListener('submit',e=>{e.preventDefault();state.preferences.region=new FormData(e.currentTarget).get('region');save();toast('Workspace preferences saved.')});
}
function bindRows(){document.querySelectorAll('[data-open]').forEach(r=>{r.onclick=()=>planDetails(r.dataset.open);r.onkeydown=e=>{if(e.key==='Enter')planDetails(r.dataset.open)}});document.querySelectorAll('#plans-table [data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action))}
function action(a){if(a==='new-plan')newPlan();else if(a==='budget')budget();else if(a==='all-plans')nav('plans');else if(a==='new-leash')newLeash();else if(a==='new-cyst')newCyst();else if(a==='new-agent')newAgent();else if(a==='export-workspace')download('telomere-workspace.json',{...state,hosts:JSON.parse(localStorage.getItem('telomere-hosts')||'[]')});else if(a==='export-plans')download('telomere-run-plans.json',state.plans.map(requestFor));else if(a==='import-receipt')$('#receipt-file').click();else if(a==='export-receipts'){const fields=['run_id','hw_class','billable_seconds','amount_usdc'];const csv=[fields.join(','),...state.receipts.map(r=>fields.map(f=>'"'+String(r[f]).replaceAll('"','""')+'"').join(','))].join('\n');download('telomere-receipts.csv',csv,'text/csv')}else if(a==='reset'){drawer('Clear this workspace?',`<div class="drawer-form"><p class="drawer-intro">This removes configurations and imported records saved on this device. Export a copy first if you need to retain them.</p><button class="pill" id="reset-export">Export workspace ↓</button><button class="pill primary" id="reset-confirm">Clear workspace data</button></div>`);$('#reset-export').onclick=()=>action('export-workspace');$('#reset-confirm').onclick=()=>{state=structuredClone(initial);localStorage.removeItem('telomere-hosts');save();closeDrawer();render();toast('Workspace data cleared.')};}}
$('#receipt-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2e6)throw Error('Keep receipt files under 2 MB.');const raw=JSON.parse(await file.text()),rows=Array.isArray(raw)?raw:[raw];if(!rows.length||rows.some(r=>!r||typeof r.run_id!=='string'||!['string','number'].includes(typeof r.hw_class)||!Number.isFinite(Number(r.billable_seconds))||!Number.isFinite(Number(r.amount_usdc))||+r.billable_seconds<0||+r.amount_usdc<0))throw Error('Receipt files require run_id, hw_class, billable_seconds, and amount_usdc.');let count=0;rows.forEach(r=>{if(!state.receipts.some(x=>x.run_id===r.run_id)){state.receipts.push(r);count++}});record('Receipt import',count+' receipt records imported');save();render();toast(count+' receipt records imported.')}catch(err){toast(err.message||'Unable to read this receipt file.')}e.target.value=''};
main.openConfiguration=()=>{if(new URLSearchParams(location.search).has('configure'))history.replaceState({},'',location.pathname);let pending={};try{pending=JSON.parse(sessionStorage.getItem('telomere-pending-plan')||'{}');sessionStorage.removeItem('telomere-pending-plan')}catch{}newPlan(pending)};render();if(new URLSearchParams(location.search).has('configure'))main.openConfiguration();
